/**
 * Fone Factory — Seed Script
 * Inserts 600 mobile-phone products into MongoDB.
 *
 * Usage (from backend/ directory, with .env configured):
 *   node seed.js           → adds products (skips duplicates by name)
 *   node seed.js --clear   → drops all existing products first, then seeds
 *
 * On Render (remote):
 *   Set MONGODB_URI env var on the service, then run via Render Shell:
 *   cd backend && node seed.js --clear
 */

const mongoose = require('mongoose');
const dotenv   = require('dotenv');
dotenv.config();

const Product = require('./models/Product');

const MONGODB_URI = process.env.MONGODB_URI || 'mongodb://localhost:27017/mobile-store';
const CLEAR       = process.argv.includes('--clear');

/* ── brand colour map for visually distinct placeholder images ── */
const brandColor = {
  Samsung:  '1428A0', Apple:    '555555', Xiaomi:   'FF6900',
  OnePlus:  'F50514', Oppo:     '1D6FA4', Vivo:     '415FFF',
  Realme:   'FFC107', Nothing:  '000000', Google:   '4285F4',
  Motorola: '00479E', Other:    '6C757D',
};

const img = (brand, num) => {
  const col  = brandColor[brand] || '888888';
  const text = encodeURIComponent(`${brand}+%23${num}`);
  return [{
    url: `https://placehold.co/600x600/${col}/ffffff?text=${text}`,
    public_id: `seed_${num}`,
  }];
};

